import math
X=0.0;Y=0.0;TH=0.0
PTS={}
phase='rev'
last_t=None
stopped_wake=False
cnt=0

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def clip(v,a,b):
    return max(a,min(b,v))

def control(obs):
    global X,Y,TH,phase,last_t,stopped_wake,cnt
    cnt+=1
    dt=obs.get('dt',0.1)
    mot=obs['motion']; v=mot['v_mps']; st=obs['steer_deg']
    TH+=v*math.tan(math.radians(st))/2.75*dt
    X+=v*math.cos(TH)*dt; Y+=v*math.sin(TH)*dt
    c=math.cos(TH); s=math.sin(TH)
    views=obs.get('views') or {}
    for k,vw in views.items():
        if k=='periphery': continue
        ox,oy=vw['origin']
        for b,d in vw.get('walls',[]):
            x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
            wx=X+x*c-y*s; wy=Y+x*s+y*c
            PTS[(round(wx*5),round(wy*5))]=(wx,wy)
    rig=obs['rig']; hitch=obs['hitch_deg']
    Rx,Ry=rig['trailer_rear']
    loc=[]
    for (wx,wy) in PTS.values():
        dx=wx-X; dy=wy-Y
        x=dx*c+dy*s; y=-dx*s+dy*c
        if (x-Rx)**2+(y-Ry)**2<15**2: loc.append((x-Rx,y-Ry))
    back=180-hitch
    tgt=obs.get('target') or {}
    # gap search
    devs=list(range(-80,81,5))
    frees=[]
    for dv in devs:
        a=math.radians(back+dv); ux=math.cos(a); uy=math.sin(a)
        f=10.0
        for (px,py) in loc:
            al=px*ux+py*uy
            if al>0 and al<f and abs(px*uy-py*ux)<1.2: f=al
        frees.append(f)
    mf=max(frees)
    bi=max(range(len(devs)),key=lambda i:frees[i]-0.01*abs(devs[i]))
    lo=bi;hi=bi
    while lo>0 and frees[lo-1]>=mf-0.4: lo-=1
    while hi<len(devs)-1 and frees[hi+1]>=mf-0.4: hi+=1
    dev=(devs[lo]+devs[hi])/2.0
    if tgt.get('in_sight') and tgt.get('dist_m') is not None:
        ex,ey=rig['eye']; tb=math.radians(tgt['bearing_deg']); td=tgt['dist_m']
        tx=ex+td*math.cos(tb)-Rx; ty=ey+td*math.sin(tb)-Ry
        if tx*tx+ty*ty>1.0:
            dev=wrap(math.degrees(math.atan2(ty,tx))-back)
    free_straight=frees[devs.index(0)]
    look=-23
    if abs(hitch)>48 or phase=='fwd':
        if phase!='fwd': phase='fwd'
        if abs(hitch)<8:
            phase='rev'
        else:
            return (0.0,1.0,look)
    if len(loc)==0 and obs['t']<1.0:
        return (0.0,0.0,look)
    phid=clip(1.0*dev,-30,30)
    steer=-0.75*phid+2.5*(hitch-phid)
    steer=clip(steer,-34,34)
    sp=-1.0
    if mf<2.5: sp=-0.6
    if free_straight<0.5 and mf<0.6:
        if not stopped_wake:
            stopped_wake=True
            wake('blocked: free %.2f' % mf)
        return (steer,0.0,look)
    if cnt%20==0:
        print('t%.1f h%.1f dev%.0f mf%.1f st%.0f' % (obs['t'],hitch,dev,mf,steer))
    return (steer,sp,look)

