import math
X=0.0;Y=0.0;TH=0.0
MEM={}
phase='rev'
fx=0.0
woke=False
cnt=0

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def clip(v,a,b):
    return max(a,min(b,v))

def control(obs):
    global X,Y,TH,phase,fx,woke,cnt
    cnt+=1
    dt=obs.get('dt') or 0.1
    t=obs['t']
    mot=obs['motion']; v=mot['v_mps']; st=obs['steer_deg']
    TH+=v*math.tan(math.radians(st))/2.75*dt
    X+=v*math.cos(TH)*dt; Y+=v*math.sin(TH)*dt
    c=math.cos(TH); s=math.sin(TH)
    views=obs.get('views') or {}
    for k,vw in views.items():
        if k=='periphery' or not vw: continue
        ox,oy=vw['origin']
        for w in vw.get('walls',[]):
            b=w[0]; d=w[1]
            x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
            wx=X+x*c-y*s; wy=Y+x*s+y*c
            MEM[(round(wx*4),round(wy*4))]=(t,wx,wy)
    for kk in [k for k,p in MEM.items() if t-p[0]>8]:
        del MEM[kk]
    rig=obs['rig']; hitch=obs['hitch_deg']
    Rx,Ry=rig['trailer_rear']
    loc=[]
    for (pt,wx,wy) in MEM.values():
        dx=wx-X; dy=wy-Y
        x=dx*c+dy*s; y=-dx*s+dy*c
        if (x-Rx)**2+(y-Ry)**2<100: loc.append((x-Rx,y-Ry))
    back=180-hitch
    look=-23
    status=obs.get('status')
    if phase=='fwd' or abs(hitch)>42 or status=='JACKKNIFED':
        if phase!='fwd':
            phase='fwd'; fx=X+0.0; fy0=Y
        moved=abs(X-fx)
        if abs(hitch)<12 or moved>3.0:
            phase='rev'
        else:
            return (clip(-1.0*hitch,-34,34),0.8,look)
    devs=list(range(-90,91,5))
    frees=[]
    for dv in devs:
        a=math.radians(back+dv); ux=math.cos(a); uy=math.sin(a)
        f=7.0
        for (px,py) in loc:
            al=px*ux+py*uy
            if al>-0.3 and al<f and abs(px*uy-py*ux)<1.15: f=max(al,0.0)
        frees.append(f)
    bi=max(range(len(devs)),key=lambda i:frees[i]-0.01*abs(devs[i]))
    fb=frees[bi]
    lo=bi;hi=bi
    while lo>0 and frees[lo-1]>=fb-0.3: lo-=1
    while hi<len(devs)-1 and frees[hi+1]>=fb-0.3: hi+=1
    dev=(devs[lo]+devs[hi])/2.0
    tgt=obs.get('target') or {}
    if tgt.get('in_sight') and tgt.get('dist_m') is not None:
        ex,ey=rig['eye']; tb=math.radians(tgt['bearing_deg']); td=tgt['dist_m']
        tx=ex+td*math.cos(tb)-Rx; ty=ey+td*math.sin(tb)-Ry
        if tx*tx+ty*ty>2.0:
            dt_=wrap(math.degrees(math.atan2(ty,tx))-back)
            i=min(range(len(devs)),key=lambda j:abs(devs[j]-dt_))
            if frees[i]>=min(math.hypot(tx,ty)-0.5,4.0):
                dev=dt_
    phid=clip(-0.9*dev,-32,32)
    steer=-0.75*phid+2.0*(hitch-phid)
    steer=clip(steer,-34,34)
    i0=devs.index(0)
    near=min(frees[i0-3:i0+4])
    sp=-0.8
    if near>4 and abs(hitch-phid)<10: sp=-1.1
    if near<1.5: sp=-0.5
    if frees[i0]<0.3 and fb<0.6:
        if not woke:
            woke=True
            wake('blocked behind: free %.2f' % fb)
        return (steer,0.0,look)
    if cnt%20==0:
        print('t%.1f h%.1f dev%.0f fb%.1f f0%.1f phid%.0f st%.0f' % (t,hitch,dev,fb,frees[i0],phid,steer))
    return (steer,sp,look)

