import math
phase='fwd'
d=0.0
woke=False
def clip(v,a,b):
    return max(a,min(b,v))
def control(obs):
    global phase,d,woke
    dt=obs.get('dt') or 0.1
    v=obs['motion']['v_mps']
    h=obs['hitch_deg']
    d+=v*dt
    look=-23
    if phase=='fwd':
        if d>2.8 or (d>1.5 and abs(h)<3):
            phase='rev'
        else:
            return (0.0,0.8,look)
    # reverse holding hitch near 0
    steer=clip(2.5*h,-34,34)
    cam=(obs.get('views') or {}).get('camera') or {}
    Rx,Ry=obs['rig']['trailer_rear']
    ox,oy=cam.get('origin',[Rx,Ry]) if cam else (Rx,Ry)
    hd=math.radians(180-h)
    for w in cam.get('walls',[]) if cam else []:
        b=math.radians(w[0]); dd=w[1]
        px=dd*math.cos(b); py=dd*math.sin(b)
        al=px*math.cos(hd)+py*math.sin(hd)
        lat=-px*math.sin(hd)+py*math.cos(hd)
        if 0<al<0.35 and abs(lat)<0.8:
            if not woke:
                woke=True
                wake('rail close behind trailer h%.1f' % h)
            return (steer,0.0,look)
    return (steer,-0.5,look)

