import math
X=0.0;Y=0.0;YAW=0.0
PTS=[]
mode='fwd0'
fwd_start=(0.0,0.0)
gi=0
gt=0.0
GSEQ=[-64,-140,64,140]
lastprint=-10
nfwd=0
woke=False

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def clamp(v,a,b):
    return max(a,min(b,v))

def control(obs):
    global X,Y,YAW,PTS,mode,fwd_start,gi,gt,lastprint,nfwd,woke
    t=obs['t']; dt=obs.get('dt',0.1) or 0.1
    mo=obs['motion']; v=mo['v_mps']; st=obs['steer_deg']
    YAW+=v*math.tan(math.radians(st))/2.5*dt
    X+=v*math.cos(YAW)*dt; Y+=v*math.sin(YAW)*dt
    c=math.cos(YAW); s=math.sin(YAW)
    views=obs.get('views') or {}
    for k,vw in views.items():
        if not vw: continue
        o=vw.get('origin',[0,0])
        for w in vw.get('walls',[]) or []:
            b,d=w[0],w[1]
            if d>16: continue
            px=o[0]+d*math.cos(math.radians(b)); py=o[1]+d*math.sin(math.radians(b))
            PTS.append((t,X+px*c-py*s,Y+px*s+py*c))
    PTS=[p for p in PTS if t-p[0]<6.0]
    if len(PTS)>2000: PTS=PTS[-2000:]
    head=obs['head']
    if head.get('settled'):
        if gt==0: gt=t
        if t-gt>0.5:
            gi=(gi+1)%len(GSEQ); gt=0
    look=GSEQ[gi]
    rig=obs['rig']; R=rig['trailer_rear']; hw=rig.get('trailer_half_width',1.2)
    hitch=obs['hitch_deg']
    status=obs['status']
    rem=(obs.get('progress') or {}).get('remaining',99)
    if rem is not None and rem<-1.5 and not woke:
        woke=True; wake('past bay centre? rem %.1f'%rem)
    if mode=='fwd0':
        if math.hypot(X-fwd_start[0],Y-fwd_start[1])>1.5:
            mode='rev'
        else:
            return (clamp(-0.6*hitch,-30,30),0.9,look)
    if mode=='rev' and (abs(hitch)>45 or status=='JACKKNIFED'):
        mode='fwd'; fwd_start=(X,Y); nfwd+=1
        if nfwd>3: wake('many pull-forwards')
    if mode=='fwd':
        dist=math.hypot(X-fwd_start[0],Y-fwd_start[1])
        if (abs(hitch)<15 and dist>1.0) or dist>2.5:
            mode='rev'
        else:
            return (clamp(-0.6*hitch,-30,30),1.0,look)
    bb=math.radians(180.0-hitch); ux=math.cos(bb); uy=math.sin(bb)
    nL=None;nR=None;fL=None;fR=None
    for (_,wx,wy) in PTS:
        dx=wx-X; dy=wy-Y
        px=dx*c+dy*s; py=-dx*s+dy*c
        ex=px-R[0]; ey=py-R[1]
        al=ex*ux+ey*uy; lat=ux*ey-uy*ex
        if abs(lat)>5: continue
        if -3.5<=al<=1.5:
            if lat>=0:
                if nL is None or lat<nL: nL=lat
            else:
                if nR is None or lat>nR: nR=lat
        if 1.5<al<=7.5:
            if lat>=0:
                if fL is None or lat<fL: fL=lat
            else:
                if fR is None or lat>fR: fR=lat
    def cen(L,Rr):
        if L is not None and Rr is not None: return (L+Rr)/2
        if L is not None: return L-2.8
        if Rr is not None: return Rr+2.8
        return None
    cn=cen(nL,nR); cf=cen(fL,fR)
    if cf is None: cf=cn if cn is not None else 0.0
    if cn is None: cn=0.0
    aim=math.degrees(math.atan2(cf,4.5))+6.0*cn
    aim=clamp(aim,-40,40)
    tg=obs.get('target',{}) or {}
    spd=-0.7
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg['dist_m']<16:
        e=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
