TG=None
mode='fwd'
fx=0.0
lp=-10
woke=False

def clip(a,lo,hi):
    return max(lo,min(hi,a))

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def deq(h):
    r=math.radians(h)
    return math.degrees(math.atan(1.25*math.sin(r)/(0.85+0.3*math.cos(r))))

def fit(pts,A):
    n=len(pts)
    if n<2: return None
    ma=sum(p[0] for p in pts)/n; ml=sum(p[1] for p in pts)/n
    va=sum((p[0]-ma)**2 for p in pts)/n
    if va<0.1: m=0.0
    else:
        m=clip(sum((p[0]-ma)*(p[1]-ml) for p in pts)/n/va,-0.6,0.6)
    return ml+m*(A-ma)

def control(obs):
    global X,Y,P,W,TG,mode,fx,lp,woke
    dt=obs.get('dt') or 0.1
    t=obs['t']
    v=obs['motion']['v_mps'];d=math.radians(obs['steer_deg'])
    X+=v*math.cos(P)*dt;Y+=v*math.sin(P)*dt;P+=v*math.tan(d)/1.25*dt
