def clip(a,lo,hi):
    return max(lo,min(hi,a))

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def deq(h):
    r=math.radians(h)
    return math.degrees(math.atan(1.25*math.sin(r)/(0.85+0.3*math.cos(r))))

